    def solve(s):
        w_index = s.index('W')
        left_black = w_index
        right_black = len(s) - w_index - 1

        if left_black == 0 and right_black == 0:
            return "Chef"
        elif left_black == 0 or right_black == 0:
            return "Aleksa"
        else:
            if (left_black + right_black) % 2 == 0:
                return "Chef"
            else:
                return "Aleksa"

    t = int(sys.stdin.readline().strip())
    results = []

    for _ in range(t):
        s = sys.stdin.readline().strip()
        results.append(solve(s))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
